mapper.select:
select report_id, report_name, report_type, status, file_url, remark, create_by, create_time, update_by, update_time
from agentsec_security_report

    and report_name like concat('%', #{reportName}, '%')
    and report_type = #{reportType}
    and status = #{status}

order by create_time desc

mapper.insert:
insert into agentsec_security_report (
    report_id, tenant_id, report_name, report_type, status, file_url, remark, create_by, create_time, update_by, update_time
) values (
    #{reportId}, 'tenant_demo_001', #{reportName}, #{reportType}, #{status}, #{fileUrl}, #{remark}, #{createBy}, sysdate(), #{updateBy}, sysdate()
)
